Object.assign(CONTENT.skills, {
  bm:   { name: "반말 1 · verb endings", rule: "Take 요 off the 해요체 form: 가요 → 가, 먹어요 → 먹어, 해요 → 해. The same for -을까?, -을래?, -을게, -는데, -지. -을게 is spelled with 게, although it sounds like [께]." },
  bmn:  { name: "반말 1 · 이야/야, 나 and 너, 응 and 아니", rule: "Nouns take 이야 after a consonant and 야 after a vowel. 저 becomes 나, 제가 becomes 내가, you is 너 or 네가, 네 becomes 응 and 아니요 becomes 아니. Never mix 저 with a 반말 ending." },
  am:   { name: "아무 …이나/나 · form", rule: "아무 + noun + 이나 after a consonant, 나 after a vowel: 아무 음식이나, 아무 때나. Set forms: 아무나, 아무거나, 아무 데나, 아무 때나." },
  amu:  { name: "아무 …이나/나 · which one", rule: "아무나 is anyone, 아무거나 anything, 아무 데나 anywhere, 아무 때나 any time. With a negative it means ‘not just any’: 아무나 들어갈 수 없어요." },
  voc3: { name: "Chapter 3 words · appointments", rule: "당기다 moves a time earlier, 늦추다 and 미루다 move it later. 약속이 겹치다 is two appointments at once. 깜빡하다 is letting something slip your mind." },
  col3: { name: "Appointment verbs and reasons", rule: "약속을 잡다 / 취소하다 / 어기다, 약속이 겹치다, 시간을 당기다 / 늦추다, 사고가 나다, 일이 밀리다, 지하철을 놓치다, 비용이 들다." },
});
